export const disciplinaPorId = Object.fromEntries(DISCIPLINAS.map((d) => [d.id, d]));
/** Rótulo de uma etapa: título próprio (trilha de módulos) ou o nome da etapa comum. */
export const rotuloEtapa = (e) => e.titulo || ETAPAS[e.etapa];
